fn put_u32(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_le_bytes());
}

declarations.fn cf_code(:
fn cf_code(cf: ColumnFamily) -> u8 {
    match cf {
        ColumnFamily::Default => 0,
        ColumnFamily::Lock => 1,
        ColumnFamily::Write => 2,
    }
}

declarations.pub(crate) fn encode_batch_with_capacity:
pub(crate) fn encode_batch_with_capacity(batch: &WriteBatch, capacity: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(capacity);
    put_u32(&mut out, batch.mutations().len() as u32);
    for m in batch.mutations() {
        match m {
            Mutation::Put { cf, key, value } => {
                out.push(0);
                out.push(cf_code(*cf));
                put_u32(&mut out, key.len() as u32);
                out.extend_from_slice(key);
                put_u32(&mut out, value.len() as u32);
                out.extend_from_slice(value);
            }
            Mutation::Delete { cf, key } => {
                out.push(1);
                out.push(cf_code(*cf));
                put_u32(&mut out, key.len() as u32);
                out.extend_from_slice(key);
            }
        }
    }
    out
}

